python3 -c "
import json

# Load the JSON file to look for more structured data
with open('/app/resources/treasury_bulletin_1942_07.json', 'r') as f:
    data = json.load(f)

# Let's look for any mentions of refunds
# Search through the document
def search_json(obj, path=''):
    if isinstance(obj, dict):
        for key, value in obj.items():
            search_json(value, f'{path}.{key}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_json(item, f'{path}[{i}]')
    elif isinstance(obj, str):
        if 'refund' in obj.lower() or 'net' in obj.lower():
            print(f'{path}: {obj[:200]}')

search_json(data)
" 2>/dev/null | head -50
